CREATE TABLE "files" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "files_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"key" text NOT NULL,
	"kind" text NOT NULL,
	"content_type" text NOT NULL,
	"size_bytes" integer NOT NULL,
	"sha256" text,
	"status" text DEFAULT 'PENDING' NOT NULL,
	"owner_id" bigint,
	"uploaded_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "files_key_key" UNIQUE("key"),
	CONSTRAINT "files_kind_format" CHECK ("files"."kind" ~ '^[a-z]+[.][a-z_]+$'),
	CONSTRAINT "files_key_format" CHECK ("files"."key" ~ '^[0-9a-f-]{36}[.][a-z]{3,4}$'),
	CONSTRAINT "files_size" CHECK ("files"."size_bytes" > 0),
	CONSTRAINT "files_sha256" CHECK ("files"."sha256" IS NULL OR "files"."sha256" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "files_status" CHECK ("files"."status" IN ('PENDING', 'READY', 'DELETED')),
	CONSTRAINT "files_uploaded" CHECK (("files"."uploaded_at" IS NULL) = ("files"."sha256" IS NULL) AND ("files"."status" = 'PENDING' OR "files"."uploaded_at" IS NOT NULL))
);
